python - <<'PY'
import csv, json, urllib.request
p = inputs.input1.path
n=0; ids=[]; minp=1.0; chrom={}
with open(p, newline='') as f:
    r=csv.DictReader(f, delimiter='\t')
    for row in r:
        n += 1
        chrom[row['CHR']] = chrom.get(row['CHR'],0)+1
        try: minp=min(minp,float(row['P']))
        except: pass
        if len(ids)<3: ids.append(row['RSID'])
out={"rows":n,"min_p":minp,"chrom_counts":chrom,"network":[]}
for rs in ids:
    try:
        req=urllib.request.Request("https://rest.ensembl.org/variation/human/"+rs+"?pops=1",headers={"Content-Type":"application/json","Accept":"application/json"})
        with urllib.request.urlopen(req,timeout=30) as z:
            d=json.load(z)
        out["network"].append({"rsid":rs,"ok":True,"populations":len(d.get("populations",[]))})
    except Exception as e:
        out["network"].append({"rsid":rs,"ok":False,"error":str(e)[:160]})
with open("out.json","w") as g: json.dump(out,g,indent=2,sort_keys=True)
PY

