import csv,json,math,sys,urllib.parse,urllib.request,statistics
rows=[]; lead=None
with open(sys.argv[1],newline='') as f:
 for r in csv.DictReader(f,delimiter='\t'):
  try: p=float(r['P']); pos=int(r['POS'])
  except: continue
  if 16311190 <= pos <= 18311190:
   rows.append((r['RSID'],p,pos))
   if lead is None or p<lead[1]: lead=(r['RSID'],p,pos)
gwas={rs:-math.log10(max(p,1e-300)) for rs,p,pos in rows}
pops={
 "AFR":"1000GENOMES:phase_3:YRI",
 "EUR":"1000GENOMES:phase_3:CEU",
 "EAS":"1000GENOMES:phase_3:CHB",
 "SAS":"1000GENOMES:phase_3:PJL",
 "HIS":"1000GENOMES:phase_3:MXL"}
def ranks(v):
 order=sorted(range(len(v)),key=lambda i:v[i]); out=[0.0]*len(v); i=0
 while i<len(order):
  j=i+1
  while j<len(order) and v[order[j]]==v[order[i]]: j+=1
  z=(i+j-1)/2+1
  for k in range(i,j): out[order[k]]=z
  i=j
 return out
def corr(a,b):
 if len(a)<3:return None
 ra,rb=ranks(a),ranks(b); ma=sum(ra)/len(ra);mb=sum(rb)/len(rb)
 num=sum((x-ma)*(y-mb) for x,y in zip(ra,rb))
 den=(sum((x-ma)**2 for x in ra)*sum((y-mb)**2 for y in rb))**0.5
 return num/den if den else None
out={"lead":lead,"gwas_window_n":len(rows),"populations":{}}
for code,pop in pops.items():
 try:
  url="https://rest.ensembl.org/ld/human/"+lead[0]+"/"+urllib.parse.quote(pop,safe="")+"?window_size=1000000;r2=0"
  req=urllib.request.Request(url,headers={"Content-Type":"application/json","Accept":"application/json"})
  with urllib.request.urlopen(req,timeout=120) as z: arr=json.load(z)
  ld={}
  for x in arr:
   a=x.get("variation1");b=x.get("variation2")
   other=b if a==lead[0] else a
   try: ld[other]=max(ld.get(other,0),float(x["r2"]))
   except: pass
  common=[rs for rs in gwas if rs in ld]
  y=[gwas[rs] for rs in common]; x=[ld[rs] for rs in common]
  sig=[rs for rs in common if gwas[rs]>=4]
  out["populations"][code]={
   "ld_n":len(ld),"overlap":len(common),"spearman_all":corr(x,y),
   "spearman_sig":corr([ld[r] for r in sig],[gwas[r] for r in sig]),
   "high_ld_mean_logp": statistics.mean([gwas[r] for r in common if ld[r]>=0.5]) if any(ld[r]>=0.5 for r in common) else None,
   "low_ld_mean_logp": statistics.mean([gwas[r] for r in common if ld[r]<0.1]) if any(ld[r]<0.1 for r in common) else None,
   "leadlike_r2_08":sum(1 for r in common if ld[r]>=0.8),
   "leadlike_p_1e8":sum(1 for r in common if ld[r]>=0.8 and gwas[r]>=8),
   "error":None}
 except Exception as e: out["populations"][code]={"error":str(e)[:300]}
with open("out.json","w") as g: json.dump(out,g,indent=2,sort_keys=True)
PY

