   try: ld[other]=max(ld.get(other,0),float(q["r2"]))
   except: pass
  common=[rs for rs in gwas if rs in ld]
  sig=[rs for rs in common if gwas[rs]>=4]
  high=[gwas[r] for r in common if ld[r]>=.5]; low=[gwas[r] for r in common if ld[r]<.1]
  out["populations"][code]={"ld_n":len(ld),"overlap":len(common),
   "spearman_all":corr([ld[r] for r in common],[gwas[r] for r in common]),
   "spearman_sig":corr([ld[r] for r in sig],[gwas[r] for r in sig]),
   "high_ld_mean_logp":statistics.mean(high) if high else None,
   "low_ld_mean_logp":statistics.mean(low) if low else None,
   "high_ld_n":len(high),"low_ld_n":len(low),
   "r2_08_n":sum(ld[r]>=.8 for r in common),
   "r2_08_p8_n":sum(ld[r]>=.8 and gwas[r]>=8 for r in common)}
 except Exception as e: out["populations"][code]={"error":str(e)[:300]}
with open("out.json","w") as g:json.dump(out,g,indent=2,sort_keys=True)
