python - "$(inputs.input1.path)" <<'PY'
import csv,json,math,sys,urllib.request,statistics,time
from concurrent.futures import ThreadPoolExecutor,as_completed
rows=[]
with open(sys.argv[1],newline='') as f:
 for r in csv.DictReader(f,delimiter='\t'):
  try: rows.append({"rs":r["RSID"],"p":float(r["P"]),"pos":int(r["POS"])})
  except: pass
leads=[]
for r in sorted(rows,key=lambda x:x["p"]):
 if r["p"]>=5e-8: break
 if all(abs(r["pos"]-x["pos"])>1000000 for x in leads): leads.append(r)
 if len(leads)>=5: break
pops={"AFR":"1000GENOMES:phase_3:YRI","EUR":"1000GENOMES:phase_3:CEU","EAS":"1000GENOMES:phase_3:CHB","SAS":"1000GENOMES:phase_3:PJL","HIS":"1000GENOMES:phase_3:MXL"}
def ranks(v):
 o=sorted(range(len(v)),key=lambda i:v[i]); q=[0.0]*len(v); i=0
 while i<len(o):
  j=i+1
  while j<len(o) and v[o[j]]==v[o[i]]:j+=1
  z=(i+j+1)/2
  for k in range(i,j):q[o[k]]=z
  i=j
 return q
def corr(a,b):
 if len(a)<5:return None
 a,b=ranks(a),ranks(b);ma=sum(a)/len(a);mb=sum(b)/len(b)
 den=(sum((x-ma)**2 for x in a)*sum((y-mb)**2 for y in b))**.5
 return sum((x-ma)*(y-mb) for x,y in zip(a,b))/den if den else None
def one(lead,code,pop):
 url="https://rest.ensembl.org/ld/human/"+lead["rs"]+"/"+pop+"?window_size=500;r2=0"
 req=urllib.request.Request(url,headers={"Content-Type":"application/json","Accept":"application/json"})
 with urllib.request.urlopen(req,timeout=150) as z: arr=json.load(z)
 ld={}
 for q in arr:
  a=q.get("variation1");b=q.get("variation2");other=b if a==lead["rs"] else a
  try:ld[other]=max(ld.get(other,0),float(q["r2"]))
  except:pass
 g={r["rs"]:-math.log10(max(r["p"],1e-300)) for r in rows if abs(r["pos"]-lead["pos"])<=500000}
 common=[rs for rs in g if rs in ld]; sig=[rs for rs in common if g[rs]>=4]
 return code,lead["rs"],{"overlap":len(common),"spearman_all":corr([ld[r] for r in common],[g[r] for r in common]),"spearman_p1e4":corr([ld[r] for r in sig],[g[r] for r in sig]),"ld_n":len(ld)}
out={"leads":leads,"results":{}}
with ThreadPoolExecutor(max_workers=5) as ex:
 futs={ex.submit(one,l,c,p):(l,c) for l in leads for c,p in pops.items()}
 for f in as_completed(futs):
  l,c=futs[f];out["results"].setdefault(l["rs"],{})
  try:
   code,rs,val=f.result();out["results"][rs][code]=val
  except Exception as e:out["results"][l["rs"]][c]={"error":str(e)[:250]}
agg={}
for code in pops:
 vals=[v[code].get("spearman_all") for v in out["results"].values() if code in v and v[code].get("spearman_all") is not None]
 sig=[v[code].get("spearman_p1e4") for v in out["results"].values() if code in v and v[code].get("spearman_p1e4") is not None]
 agg[code]={"mean_all":sum(vals)/len(vals) if vals else None,"median_all":statistics.median(vals) if vals else None,"mean_sig":sum(sig)/len(sig) if sig else None,"n_loci":len(vals)}
out["aggregate"]=agg
with open("out.json","w") as g:json.dump(out,g,indent=2,sort_keys=True)
